const slides=[...document.querySelectorAll('.slide')];let idx=0;const toc=document.getElementById('toc');const bar=document.getElementById('bar');const now=document.getElementById('now');const total=document.getElementById('total');const noteText=document.getElementById('noteText');const topicNav=document.getElementById('topicNav');total.textContent=slides.length;
let lastSection='';const topicRanges=[];slides.forEach((s,i)=>{const sec=s.dataset.section||'Section';if(sec!==lastSection){if(topicRanges.length)topicRanges[topicRanges.length-1].end=i-1;topicRanges.push({section:sec,start:i,end:slides.length-1});const div=document.createElement('div');div.className='tocSection';div.textContent=sec;toc.appendChild(div);lastSection=sec}const b=document.createElement('button');b.className='tocItem';b.innerHTML=`<span class="tocNum">${i+1}</span><span class="tocText">${s.dataset.title}</span>`;b.onclick=()=>go(i);toc.appendChild(b)});
if(topicRanges.length)topicRanges[topicRanges.length-1].end=slides.length-1;
topicRanges.forEach((r,topicIndex)=>{const b=document.createElement('button');b.className='topicJump';b.dataset.start=r.start;b.dataset.end=r.end;b.innerHTML=`<span>${topicIndex+1}. ${r.section}</span>`;b.onclick=()=>go(r.start);topicNav.appendChild(b)});
function buildPrintNotes(){slides.forEach((s,i)=>{if(s.querySelector('.printOnly'))return;const panel=document.createElement('div');panel.className='printOnly';const title=s.dataset.title||`Slide ${i+1}`;const sec=s.dataset.section||'';const note=s.dataset.note||'';const items=[];s.querySelectorAll('.card h3,.layerInfo h3,.callout,.pill,.tag,.stepItem,.stackTile,.interfaceLayer,.principleBigCard,.principleCard').forEach(el=>{let t=el.textContent.replace(/\s+/g,' ').trim();if(t&&t.length>8&&!items.includes(t))items.push(t)});panel.innerHTML=`<h3>Print notes: ${sec} — ${title}</h3>${note?`<p class="small"><b>Teaching note:</b> ${note}</p>`:''}<ul>${items.slice(0,12).map(t=>`<li>${t}</li>`).join('')}</ul>`;s.appendChild(panel)})}
buildPrintNotes();
function go(n){idx=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('active',i===idx));document.querySelectorAll('.tocItem').forEach((b,i)=>b.classList.toggle('active',i===idx));now.textContent=idx+1;bar.style.width=((idx+1)/slides.length*100)+'%';noteText.textContent=slides[idx].dataset.note||'-';document.querySelectorAll('.topicJump').forEach(b=>{const st=+b.dataset.start,en=+b.dataset.end;b.classList.toggle('active',idx>=st&&idx<=en)});slides[idx].scrollIntoView({block:'nearest',inline:'nearest'});}go(0);
function setFocusMode(on){document.body.classList.toggle('focusMode',on);const btn=document.getElementById('fullscreenBtn');if(btn)btn.textContent=on?'Exit full slide':'Full slide';if(on&&document.documentElement.requestFullscreen){document.documentElement.requestFullscreen().catch(()=>{});}else if(!on&&document.fullscreenElement&&document.exitFullscreen){document.exitFullscreen().catch(()=>{});}setTimeout(()=>go(idx),60)}
document.getElementById('nextBtn').onclick=()=>go(idx+1);document.getElementById('prevBtn').onclick=()=>go(idx-1);document.getElementById('resetBtn').onclick=()=>{go(0);showToast('Lesson reset')};document.getElementById('notesBtn').onclick=()=>document.getElementById('notesPanel').classList.toggle('open');document.getElementById('fullscreenBtn').onclick=()=>setFocusMode(!document.body.classList.contains('focusMode'));document.getElementById('printBtn').onclick=()=>{buildPrintNotes();window.print()};document.getElementById('darkBtn').onclick=()=>{document.body.classList.toggle('dark')};document.getElementById('menuBtn').onclick=()=>document.getElementById('drawer').classList.add('open');document.getElementById('closeMenuBtn').onclick=()=>document.getElementById('drawer').classList.remove('open');document.querySelectorAll('.topTopic').forEach(b=>b.onclick=()=>go(+b.dataset.start-1));
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('focusMode')});document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();go(idx+1)}if(e.key==='ArrowLeft'){e.preventDefault();go(idx-1)}if(e.key.toLowerCase()==='d')document.body.classList.toggle('dark');if(e.key.toLowerCase()==='f'){e.preventDefault();setFocusMode(!document.body.classList.contains('focusMode'))}if(e.key==='Escape'&&document.body.classList.contains('focusMode'))setFocusMode(false)});function showToast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),900)}
// quizzes
// Randomize answer choices in any built-in quiz blocks
document.querySelectorAll('.quiz').forEach(q=>shuffleChildren(q));
document.querySelectorAll('.quiz').forEach(q=>{q.querySelectorAll('.choice').forEach(c=>{c.onclick=()=>{q.querySelectorAll('.choice').forEach(x=>x.classList.remove('selected','correct','wrong'));const ok=c.dataset.correct==='true';c.classList.add(ok?'correct':'wrong');const f=document.getElementById(q.dataset.feedback);if(f)f.innerHTML=ok?'<span class="okText">Correct.</span>':'<span class="wrongText">Try again.</span>'}})});
// Real-life car analogy
const carLayerData={
  goal:{
    flightTitle:'Passenger goal',
    flightText:'The passenger begins with a high-level objective, such as “I want to go to Chiang Mai.” This shows that a complex task begins with one goal, but the goal cannot be completed without several supporting steps.',
    compareTitle:'Passenger goal ⇄ Application layer',
    compareText:'The passenger decides the high-level goal. In networking, the Application layer starts the communication goal, such as opening a website or sending email.',
    flightChips:['Real-life focus','Trip goal starts the process'],
    compareChips:['Real-life: travel goal','Network: application service'],
    real:'The passenger goal starts the trip.',
    net:'The application starts communication.',
    example:'Go to Chiang Mai ⇄ Open a web page.',
    question:'Which lower layers must help make the goal happen?'
  },
  booking:{
    flightTitle:'Booking control',
    flightText:'Booking manages details such as ticket confirmation, passenger name, seat, baggage, and schedule. This step controls how the trip will be handled.',
    compareTitle:'Booking control ⇄ Transport layer',
    compareText:'Booking manages trip details. In networking, the Transport layer manages delivery details such as ports, reliability, order, and flow control.',
    flightChips:['Real-life focus','Controls trip details'],
    compareChips:['Real-life: trip control','Network: delivery control'],
    real:'Ticket and seat details control the trip experience.',
    net:'TCP/UDP control how application data is delivered.',
    example:'Seat + baggage ⇄ port + reliable delivery.',
    question:'Why is booking control different from route selection?'
  },
  route:{
    flightTitle:'Flight route',
    flightText:'The airline chooses the path from source airport to destination airport, possibly with transit points. This step is about selecting the route to the destination.',
    compareTitle:'Flight route ⇄ Network layer',
    compareText:'A flight route chooses the path between airports. In networking, the Network layer chooses paths across networks using IP addressing and routing.',
    flightChips:['Real-life focus','Chooses the travel path'],
    compareChips:['Real-life: route between airports','Network: route packets'],
    real:'Airline or air traffic planning determines the route.',
    net:'Routers choose the next hop using IP information.',
    example:'BKK → CNX ⇄ source IP → destination IP.',
    question:'What changes if the route has a transit airport?'
  },
  gate:{
    flightTitle:'Gate / boarding',
    flightText:'At the local airport, passengers go through gate handling, boarding, and local checks. This is a local step that happens at one airport segment.',
    compareTitle:'Gate / boarding ⇄ Data Link layer',
    compareText:'Gate handling is local to one airport segment. In networking, the Data Link layer handles one-link delivery using frames and MAC addresses.',
    flightChips:['Real-life focus','Local airport handling'],
    compareChips:['Real-life: local airport segment','Network: one-link frame delivery'],
    real:'Gate processes handle one local segment.',
    net:'Frames move across one link at a time.',
    example:'Boarding gate ⇄ Ethernet / Wi-Fi frame delivery.',
    question:'Why can local handling change at each airport or link?'
  },
  aircraft:{
    flightTitle:'Aircraft / runway',
    flightText:'The aircraft, runway, and radio/physical systems create the actual physical movement of the trip. This is the most concrete part of the journey.',
    compareTitle:'Aircraft / runway ⇄ Physical layer',
    compareText:'Aircraft, runway, and physical systems make real movement possible. In networking, the Physical layer sends bits as electrical, optical, or radio signals.',
    flightChips:['Real-life focus','Actual physical movement'],
    compareChips:['Real-life: actual movement','Network: real signal'],
    real:'Aircraft and runway create physical movement.',
    net:'Cable, fiber, or radio carries bits as signals.',
    example:'Plane takes off ⇄ bits travel on media.',
    question:'What is the most concrete part of communication?'
  }
};
let flightCompareMode = false;
function setFlightCompareMode(showCompare){
  flightCompareMode = showCompare;
  document.querySelectorAll('#flightCompareControls button').forEach(btn=>btn.classList.remove('active'));
  const onBtn = document.getElementById(showCompare ? 'showFlightCompareBtn' : 'showFlightOnlyBtn');
  if(onBtn) onBtn.classList.add('active');
  document.querySelectorAll('.compareOnly').forEach(el=>el.style.opacity = showCompare ? '1' : '0');
  document.querySelectorAll('.compareOnly').forEach(el=>el.style.pointerEvents = showCompare ? 'auto' : 'none');
  const hint = document.getElementById('flightCompareHint');
  if(hint){
    hint.innerHTML = showCompare
      ? 'Network model side is now visible. Compare each flight step with the matching network-layer idea.'
      : '';
  }
  const active = document.querySelector('.carLayerBtn.active');
  renderCarLayer(active ? active.dataset.k : 'goal');
}
function renderCarLayer(k){
  document.querySelectorAll('.carLayerBtn').forEach(b=>b.classList.toggle('active',b.dataset.k===k));
}
document.querySelectorAll('.carLayerBtn').forEach(b=>b.onclick=()=>renderCarLayer(b.dataset.k));
document.getElementById('showFlightOnlyBtn')?.addEventListener('click',()=>setFlightCompareMode(false));
document.getElementById('showFlightCompareBtn')?.addEventListener('click',()=>setFlightCompareMode(true));
setFlightCompareMode(false);
// Principles



const principle={
  service:['Service','A layer provides a service to the layer above. Example: Application asks Transport to help send data.','<div class="pill">above layer asks</div><div class="pill">below layer helps</div>'],
  protocol:['Protocol','Same layers on different hosts follow the same rules logically. Example: TCP rules are understood by TCP on both hosts.','<div class="pill">same layer rules</div><div class="pill">logical relationship</div>'],
  modular:['Modularity','A layer can change internally if its service remains clear. Example: Ethernet can change to Wi‑Fi while the web app still works.','<div class="pill">change one part</div><div class="pill">system still works</div>']
};
document.querySelectorAll('#principleBtns .principleBigCard').forEach(b=>b.onclick=()=>{
  document.querySelectorAll('#principleBtns .principleBigCard').forEach(x=>x.classList.remove('active'));
  b.classList.add('active');
  const d=principle[b.dataset.mode];
  document.getElementById('principleInfo').innerHTML=`<h3>${d[0]}</h3><p>${d[1]}</p><div style="margin-top:8px">${d[2]}</div>`;
});
// Layer data
const osi=[
{n:7,name:'Application',cls:'layer7',fn:'Provides network services for user-facing applications such as web browsing, email, and file transfer.',ex:'HTTP, FTP, SMTP, DNS, Telnet',pdu:'Data',svc:'User-facing application services'},
{n:6,name:'Presentation',cls:'layer6',fn:'Formats data so sender and receiver understand it. It handles encoding, compression, encryption, and decryption.',ex:'JPEG, MPEG, SSL/TLS',pdu:'Data',svc:'Data format, encryption, and compression'},
{n:5,name:'Session',cls:'layer5',fn:'Starts, manages, maintains, and ends communication sessions between applications.',ex:'NetBIOS, RPC, PPTP',pdu:'Data',svc:'Session setup, management, and termination'},
{n:4,name:'Transport',cls:'layer4',fn:'Provides end-to-end delivery. It handles segmentation, ports, flow control, and reliability when needed.',ex:'TCP, UDP',pdu:'Segment',svc:'End-to-end delivery and port control'},
{n:3,name:'Network',cls:'layer3',fn:'Provides logical addressing and routing so packets can travel across multiple networks.',ex:'IP, ICMP, OSPF, RIP, BGP',pdu:'Packet',svc:'Logical addressing and routing'},
{n:2,name:'Data Link',cls:'layer2',fn:'Sends frames across a local link. It uses MAC addresses, media access control, and frame error checking.',ex:'Ethernet, PPP, Switch, Bridge',pdu:'Frame',svc:'Local link frame delivery'},
{n:1,name:'Physical',cls:'layer1',fn:'Transmits raw bits as electrical, optical, or radio signals through the physical medium.',ex:'RJ45, Fiber Optic, Hub, Repeater',pdu:'Bits',svc:'Signals and transmission media'}];
function makeLayerButton(d,prefix){return `<button class="layerBtn ${d.cls}" data-layer="${d.n}"><span>Layer ${d.n} • ${d.name}</span><small>${d.pdu}</small></button>`}
function renderOsi(target,infoId){
  const targetEl=document.getElementById(target);
  const infoEl=document.getElementById(infoId);
  if(!targetEl || !infoEl) return;
  targetEl.innerHTML=osi.map(d=>makeLayerButton(d)).join('');
  targetEl.querySelectorAll('.layerBtn').forEach(b=>b.onclick=()=>{
    targetEl.querySelectorAll('.layerBtn').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');
    const d=osi.find(x=>x.n==b.dataset.layer);
    infoEl.classList.remove('layer7','layer6','layer5','layer4','layer3','layer2','layer1','layer7bg','layer6bg','layer5bg','layer4bg','layer3bg','layer2bg','layer1bg');
    infoEl.classList.add(d.cls);
    infoEl.innerHTML=`<h3>Layer ${d.n}: ${d.name}</h3><p>${d.fn}</p><div class="osiServiceBox"><b>Service</b><span>${d.svc}</span></div><div class="pill">PDU: ${d.pdu}</div><div class="pill">Examples: ${d.ex}</div>`;
  });
}
renderOsi('osiOverviewStack','osiOverviewInfo');
renderOsi('osiLayerBtns','osiLayerInfo');
document.querySelector('#osiOverviewStack .layerBtn')?.click();
document.querySelector('#osiLayerBtns .layerBtn')?.click();
const osiIntroData={
  what:['What is it?','<b>OSI</b> stands for <b>Open Systems Interconnection</b>. It is a conceptual reference model that divides network communication into seven layers.','<div class="pill">Conceptual model</div><div class="pill">7 layers</div><div class="pill">Common language</div>'],
  who:['Who developed it?','The OSI reference model was developed by the <b>International Organization for Standardization (ISO)</b> as a standard way to describe open systems communication.','<div class="pill">Developed by ISO</div><div class="pill">Reference model</div><div class="pill">Open systems communication</div>'],
  why:['Why useful?','OSI is useful for learning and troubleshooting because it separates communication into clear responsibilities: application service, delivery control, routing, local link delivery, and physical signals.','<div class="pill">Learning</div><div class="pill">Design vocabulary</div><div class="pill">Troubleshooting by layer</div>']
};
function renderOsiIntro(k){
  document.querySelectorAll('#osiIntroBtns button').forEach(b=>b.classList.toggle('active',b.dataset.k===k));
  const d=osiIntroData[k];
  const box=document.getElementById('osiIntroInfo');
  if(box) box.innerHTML=`<h3>${d[0]}</h3><p>${d[1]}</p><div style="margin-top:10px">${d[2]}</div>`;
}
document.querySelectorAll('#osiIntroBtns button').forEach(b=>b.onclick=()=>renderOsiIntro(b.dataset.k));
if(document.getElementById('osiIntroBtns')) renderOsiIntro('what');
const tcp=[
{n:5,name:'Application',cls:'layer7',fn:'Provides network services directly used by applications. In TCP/IP, this layer also covers many OSI presentation/session functions.',ex:'HTTP/HTTPS, DNS, SMTP/IMAP, FTP, SSH',pdu:'Data',svc:'User-facing network services',icons:[['🌐','Browser'],['💬','Chat'],['📧','Email'],['🔎','DNS'],['📁','FTP']]},
{n:4,name:'Transport',cls:'layer4',fn:'Provides process-to-process delivery using ports. TCP can provide reliable ordered delivery; UDP provides simpler, faster delivery.',ex:'TCP, UDP',pdu:'Segment',svc:'Ports, segmentation, reliability when needed',icons:[['🔢','Ports'],['✅','TCP'],['⚡','UDP'],['🧩','Segment'],['↕️','Flow']]},
{n:3,name:'Network',cls:'layer3',fn:'Uses IP addressing and routing to move packets from source host to destination host across networks.',ex:'IPv4, IPv6, ICMP, routing protocols',pdu:'Packet',svc:'Logical addressing and routing',icons:[['📡','Router'],['🌍','IP'],['🧭','Route'],['📦','Packet'],['⏱️','TTL']]},
{n:2,name:'Data Link',cls:'layer2',fn:'Handles local link delivery. It frames data for one link and uses MAC addressing and media access rules.',ex:'Ethernet, Wi‑Fi, PPP, VLAN',pdu:'Frame',svc:'One-link frame delivery',icons:[['🔀','Switch'],['🏷️','MAC'],['🧱','Frame'],['📶','Wi‑Fi'],['✅','CRC']]},
{n:1,name:'Physical',cls:'layer1',fn:'Moves bits as real signals through copper cable, fiber, radio, or other media.',ex:'UTP/STP, Fiber, Radio, Bluetooth, 4G/5G',pdu:'Bits',svc:'Signals and transmission media',icons:[['🔢','Bits'],['🔌','UTP'],['🧵','Fiber'],['📻','Radio'],['〰️','Signal']]}];
function renderTcpLayers(){
  const stack=document.getElementById('tcpBtns');
  const info=document.getElementById('tcpInfo');
  if(!stack || !info) return;
  stack.innerHTML=tcp.map(d=>`<button class="layerBtn ${d.cls}" data-layer="${d.n}"><div class="tcpLayerMain"><span>Layer ${d.n}: ${d.name}</span><div class="tcpIconRow">${d.icons.map(i=>`<div class="tcpIconTag"><span>${i[0]}</span><span>${i[1]}</span></div>`).join('')}</div></div><small>${d.pdu}</small></button>`).join('');
  stack.querySelectorAll('.layerBtn').forEach(b=>b.onclick=()=>{
    stack.querySelectorAll('.layerBtn').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');
    const d=tcp.find(x=>x.n==b.dataset.layer);
    info.classList.remove('layer7','layer4','layer3','layer2','layer1');
    info.style.background='';
    info.style.borderColor='';
    info.classList.add(d.cls);
    info.innerHTML=`<h3>Layer ${d.n}: ${d.name}</h3><p>${d.fn}</p><div class="tcpServiceBox"><b>Service</b><span>${d.svc}</span></div><div class="pill">PDU: ${d.pdu}</div><div class="pill">Examples: ${d.ex}</div><div class="tcpLayerIconBox">${d.icons.map(i=>`<div class="tcpLayerIconChip"><span>${i[0]}</span><span>${i[1]}</span></div>`).join('')}</div>`;
  });
  stack.querySelector('.layerBtn')?.click();
}
const tcpIntroData={
  what:['What is TCP/IP?','<b>TCP/IP</b>, or the <b>Internet Protocol Suite</b>, is the practical protocol family used to connect real networks and the Internet.','<div class="pill">Real Internet model</div><div class="pill">Protocol suite</div><div class="pill">Used in practice</div>'],
  why:['Why practical?','TCP/IP works across many different link technologies, from Ethernet and Wi‑Fi to fiber and mobile networks. This flexibility is why it became the basis of the Internet.','<div class="pill">Flexible</div><div class="pill">Scalable</div><div class="pill">Interoperable</div>'],
  layers:['5-layer vs 4-layer view','<b>5-layer view</b> separates <b>Data Link</b> and <b>Physical</b>, so it is useful for detailed teaching, PDU, frames, bits, cables, and signals. <b>4-layer view</b> combines them as <b>Link / Network Access</b>, so it is useful for compact TCP/IP overview. Both are correct; they use different levels of detail.','']
};
function renderTcpIntro(k){
  document.querySelectorAll('#tcpIntroBtns button').forEach(b=>b.classList.toggle('active',b.dataset.k===k));
  const d=tcpIntroData[k];
  const box=document.getElementById('tcpIntroInfo');
  if(box) box.innerHTML=`<h3>${d[0]}</h3><p>${d[1]}</p><div style="margin-top:10px">${d[2]}</div>`;
}
document.querySelectorAll('#tcpIntroBtns button').forEach(b=>b.onclick=()=>renderTcpIntro(b.dataset.k));
if(document.getElementById('tcpIntroBtns')) renderTcpIntro('what');
renderTcpLayers();
// Network physical/logical
const netInfo={
  physical:[
    'Physical path',
    'The orange dot now travels both directions. It pauses at Host A, Switch, Router, Switch, and Host B so students can see each physical hop clearly.',
    '<div class="pill">actual path</div><div class="pill">device by device</div><div class="pill">bits/signals on media</div>'
  ],
  logical:[
    'Logical view',
    'The purple dot now pauses at each TCP/IP layer on the request path and again on the return path, showing encapsulation and decapsulation on both hosts.',
    '<div class="pill">down sender stack</div><div class="pill">across network path</div><div class="pill">up receiver stack</div>'
  ]
};
function setNetMode(m){
  document.querySelectorAll('.netMode').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));
  document.querySelectorAll('.physicalLine').forEach(l=>l.classList.toggle('active',m==='physical'));
  document.querySelectorAll('.tcpLogicalTravel').forEach(p=>p.classList.toggle('active',m==='logical'));
  const packet=document.getElementById('netPacket');
  if(packet) packet.classList.toggle('run',m==='physical');
  const logicDot=document.getElementById('tcpLogicDot');
  if(logicDot) logicDot.classList.toggle('run',m==='logical');
  const d=netInfo[m];
  const box=document.getElementById('netInfo');
  if(box) box.innerHTML=`<h3>${d[0]}</h3><p>${d[1]}</p><div style="margin-top:10px">${d[2]}</div>`;
}
document.querySelectorAll('.netMode').forEach(b=>b.onclick=()=>setNetMode(b.dataset.mode));
if(document.querySelector('.netMode')) setNetMode('physical');
const conceptModeData={
  logical:['Logical path / Layer flow','Data moves down the sender stack, crosses the network path, moves up the receiver stack, then loops back so students can watch the full travel repeatedly.'],
  physical:['Physical path','The orange dot shows the real signal/data path at the physical level, moving from the sender physical layer through links and devices to the receiver physical layer.']
};
function setConceptMode(m){
  document.querySelectorAll('#conceptModeBtns button').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));
  document.querySelectorAll('.s2PhysicalLine').forEach(l=>l.classList.toggle('active',m==='physical'));
  document.querySelectorAll('.s2LogicPath').forEach(l=>l.classList.toggle('active',m==='logical'));
  document.querySelectorAll('.s2PeerLine').forEach(l=>l.classList.toggle('active',m==='logical'));
  const pkt=document.getElementById('conceptPacket');
  if(pkt)pkt.classList.toggle('run',m==='physical');
  const logicDot=document.getElementById('conceptLogicDot');
  if(logicDot)logicDot.classList.toggle('run',m==='logical');
  const d=conceptModeData[m];
  const info=document.getElementById('conceptInfo');
  const extra=m==='logical'
    ? '<div class="pill">down sender stack</div><div class="pill">across network path</div><div class="pill">up receiver stack</div><div class="pill">loops back with layer stops</div>'
    : '<div class="pill">starts at sender physical layer</div><div class="pill">moves through links and devices</div><div class="pill">ends at receiver physical layer</div>';
  if(info)info.innerHTML=`<h3>${d[0]}</h3><p>${d[1]}</p><div style="margin-top:8px">${extra}</div><p class="small" style="margin-top:10px"><b>Remember:</b> logical flow explains layer processing; physical path shows where the signal actually moves.</p>`;
}
document.querySelectorAll('#conceptModeBtns button').forEach(b=>b.onclick=()=>setConceptMode(b.dataset.mode)); if(document.getElementById('conceptModeBtns')) setConceptMode('physical');


const tcpCompareData={
  app:['OSI L7–L5 → TCP/IP L5 Application','TCP/IP L5 Application combines the upper OSI tasks: user network services, data format/encryption, and session or conversation control.','<div class="pill">User services</div><div class="pill">Format / encryption</div><div class="pill">Session control</div>'],
  transport:['OSI L4 → TCP/IP L4 Transport','Both models use L4 Transport for process-to-process delivery, ports, segmentation, reliability, and ordering when needed.','<div class="pill">Ports</div><div class="pill">Reliability</div><div class="pill">Segments</div>'],
  network:['OSI L3 → TCP/IP L3 Network','Both models use L3 Network for logical addressing and routing packets between different networks.','<div class="pill">IP addressing</div><div class="pill">Routing</div><div class="pill">Packets</div>'],
  datalink:['OSI L2 → TCP/IP L2 Data Link','Both 5-layer views use L2 Data Link for local-hop delivery, frames, MAC addressing, and link access rules.','<div class="pill">Frames</div><div class="pill">MAC</div><div class="pill">Local link</div>'],
  physical:['OSI L1 → TCP/IP L1 Physical','Both models use L1 Physical for raw bits, signals, media, connectors, and transmission timing.','<div class="pill">Bits</div><div class="pill">Signals</div><div class="pill">Media</div>']
};
const mapGroups={app:['l7','l6','l5','app'],transport:['l4','transport'],network:['l3','network'],datalink:['l2','datalink'],physical:['l1','physical']};
function setTcpMapDraw(k){
  document.querySelectorAll('.modelMapCanvas .mapBridge').forEach(b=>b.classList.toggle('active',b.dataset.k===k));
  document.querySelectorAll('.modelMapCanvas .hot').forEach(el=>el.classList.remove('hot'));
  const activeClasses = mapGroups[k] || [];
  activeClasses.forEach(cls=>document.querySelectorAll('.map-'+cls).forEach(el=>el.classList.add('hot')));
  // Highlight inner OSI layers inside the active OSI group too, so the mapping is visually clear.
  if(k==='app'){
