];
let encDecIndex=0, encDecTimer=null;
const rowOrder=['app','transport','network','link','physical'];
function setEncDecStep(i){
  const phase=document.getElementById('encDecPhase');
  if(!phase) return;
  encDecIndex=(i+encDecSteps.length)%encDecSteps.length;
  const s=encDecSteps[encDecIndex];
  phase.className='phasePill '+s.phaseClass;
  phase.textContent=s.phase;
  document.getElementById('encDecTitle').textContent=s.title;
  document.getElementById('encDecPdu').textContent='PDU: '+s.pdu;
  document.getElementById('encDecExplain').textContent=s.explain;
  document.getElementById('encDecCounter').textContent=`Step ${encDecIndex+1} / ${encDecSteps.length}`;
  document.getElementById('ed17Location').textContent=s.location;
  document.getElementById('ed17Direction').textContent=s.direction;
  document.getElementById('ed17Action').textContent=s.action;

  document.querySelectorAll('#senderStackMini .miniFlowLayer,#receiverStackMini .miniFlowLayer').forEach(el=>el.classList.remove('active','done'));
  document.querySelectorAll('.ed17Row').forEach(row=>{
    row.classList.remove('active','done','visible');
    const idx=rowOrder.indexOf(row.dataset.layer);
    const activeIdx=rowOrder.indexOf(s.layer);

    if(s.host==='sender'){
      if(idx<=activeIdx) row.classList.add('visible');
      if(idx<activeIdx) row.classList.add('done');
    } else if(s.host==='both'){
      if(idx<=activeIdx) row.classList.add('visible');
    } else if(s.host==='receiver'){
      /* During decapsulation, rows above the current layer vanish.
         Example:
         - at Data Link: Application, Transport, Network vanish
         - at Network: Application, Transport vanish */
      if(idx>=activeIdx) row.classList.add('visible');
      if(idx>activeIdx) row.classList.add('done');
    }

    if(row.dataset.layer===s.layer) row.classList.add('active');
    if(s.host==='both' && row.dataset.layer==='physical') row.classList.add('active');
  });
  if(s.host==='sender' || s.host==='both'){
    const t=document.querySelector(`#senderStackMini .miniFlowLayer[data-layer="${s.layer}"]`);
    if(t) t.classList.add('active');
  }
  if(s.host==='receiver' || s.host==='both'){
    const t=document.querySelector(`#receiverStackMini .miniFlowLayer[data-layer="${s.layer}"]`);
    if(t) t.classList.add('active');
  }
  document.querySelectorAll('#encDecTimeline button').forEach((b,j)=>{b.classList.toggle('active',j===encDecIndex);b.classList.toggle('done',j<encDecIndex)});
}
function buildEncDecTimeline(){
  const t=document.getElementById('encDecTimeline');
  if(!t) return;
  const labels=['1 Data','2 Segment','3 Packet','4 Frame','5 Bits','6 Frame','7 Packet','8 Segment','9 Data'];
  t.innerHTML=labels.map((label,i)=>`<button data-i="${i}">${label}</button>`).join('');
  t.querySelectorAll('button').forEach(b=>b.onclick=()=>{stopEncDecAuto();setEncDecStep(+b.dataset.i)});
  document.getElementById('encDecPrev').onclick=()=>{stopEncDecAuto();setEncDecStep(encDecIndex-1)};
  document.getElementById('encDecNext').onclick=()=>{stopEncDecAuto();setEncDecStep(encDecIndex+1)};
  document.getElementById('encDecPlay').onclick=()=>{
    const btn=document.getElementById('encDecPlay');
    if(encDecTimer){stopEncDecAuto();return;}
    btn.textContent='⏸ Pause';
    encDecTimer=setInterval(()=>setEncDecStep(encDecIndex+1),1600);
  };
  document.querySelectorAll('.ed17NavStep,.ed17Jump').forEach(el=>el.onclick=()=>{stopEncDecAuto();setEncDecStep(+el.dataset.step)});
  setEncDecStep(0);
}
function stopEncDecAuto(){
  if(encDecTimer){clearInterval(encDecTimer);encDecTimer=null;}
  const btn=document.getElementById('encDecPlay');
  if(btn) btn.textContent='▶ Play';
}
