// Randomize answers/options used in activity slides
function shuffleArray(arr){
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}
function shuffleChildren(container){
  if(!container) return;
  shuffleArray([...container.children]).forEach(child=>container.appendChild(child));
}

