// Slide 20 v5: hover/tap definition tooltip for each protocol chip
(function(){
  const chips = document.querySelectorAll('.protoHoverChip');
  if(!chips.length) return;
  let box = document.querySelector('.protoHoverBox');
  if(!box){
    box = document.createElement('div');
    box.className = 'protoHoverBox';
    box.setAttribute('role','tooltip');
    document.body.appendChild(box);
  }
  function setBoxContent(chip){
    const proto = chip.dataset.proto || chip.textContent.trim();
    const stand = chip.dataset.stand || 'Protocol / technology';
    const purpose = chip.dataset.purpose || '';
    box.innerHTML = `<div class="protoHoverTitle"><span>${proto}</span><span class="protoHoverBadge">protocol info</span></div>
      <div class="protoHoverLine"><b>Stands for</b><span>${stand}</span></div>
      <div class="protoHoverLine"><b>Used for</b><span>${purpose}</span></div>`;
  }
  function positionBox(chip){
    const r = chip.getBoundingClientRect();
    const pad = 12;
    const bw = box.offsetWidth || 330;
    const bh = box.offsetHeight || 140;
    let left = r.right + 36;
    // Place the tooltip lower than the hovered protocol chip so it does
    // not cover the protocol row/layer where the cursor is located.
    let top = r.bottom + 22;
    if(left + bw > window.innerWidth - pad) left = Math.max(pad, r.left - bw - 36);
    if(left < pad) left = pad;
    if(top + bh > window.innerHeight - pad) top = Math.max(pad, r.top - bh - 22);
    if(top < pad) top = pad;
    box.style.left = left + 'px';
    box.style.top = top + 'px';
  }
  function showTip(chip){
    setBoxContent(chip);
    box.classList.add('show');
    positionBox(chip);
    chip.setAttribute('aria-describedby','proto-hover-tip');
    box.id = 'proto-hover-tip';
  }
  function hideTip(){
    box.classList.remove('show');
  }
  chips.forEach(chip=>{
    chip.addEventListener('mouseenter',()=>showTip(chip));
    chip.addEventListener('mousemove',()=>positionBox(chip));
    chip.addEventListener('mouseleave',hideTip);
    chip.addEventListener('focus',()=>showTip(chip));
    chip.addEventListener('blur',hideTip);
    chip.addEventListener('click',(e)=>{
      e.stopPropagation();
      showTip(chip);
    });
  });
  window.addEventListener('resize',hideTip);
  document.addEventListener('keydown',e=>{ if(e.key==='Escape') hideTip(); });
})();

// Chapter 3 practice slides interactions: drag/drop matching + rearrangement
(function(){
  const bank = document.getElementById('ch3ProtocolBank');
  let selectedChip = null;

  function attachChipEvents(chip){
    chip.setAttribute('draggable','true');
    chip.addEventListener('click',()=>{
      document.querySelectorAll('.ch3Chip').forEach(c=>c.classList.remove('selected'));
      chip.classList.add('selected');
      selectedChip = chip;
    });
    chip.addEventListener('dragstart',e=>{
      selectedChip = chip;
      chip.classList.add('selected');
      e.dataTransfer.setData('text/plain', chip.dataset.proto || chip.textContent.trim());
      e.dataTransfer.effectAllowed = 'move';
    });
    chip.addEventListener('dragend',()=>chip.classList.remove('selected'));
  }

  function placeChip(drop, chip){
    if(!drop || !chip) return;
    const current = drop.querySelector('.ch3Chip');
    if(current && bank) bank.appendChild(current);
    drop.appendChild(chip);
    chip.classList.remove('selected','good','bad');
    selectedChip = null;
    document.querySelectorAll('.ch3Drop').forEach(d=>d.classList.remove('good','bad'));
    const feedback = document.getElementById('ch3MatchFeedback');
    if(feedback) feedback.textContent = 'Good. Continue matching, then click Check matches.';
  }

  if(bank){
    bank.querySelectorAll('.ch3Chip').forEach(attachChipEvents);
    function shuffleProtocolBank(){
      if(!bank) return;
      shuffleArray([...bank.querySelectorAll('.ch3Chip')]).forEach(chip=>bank.appendChild(chip));
    }
    shuffleProtocolBank();

    document.querySelectorAll('.ch3Drop').forEach(drop=>{
      drop.addEventListener('click',()=>{
        if(selectedChip) placeChip(drop, selectedChip);
      });
      drop.addEventListener('dragover',e=>{
        e.preventDefault();
        drop.classList.add('over');
        e.dataTransfer.dropEffect = 'move';
      });
      drop.addEventListener('dragleave',()=>drop.classList.remove('over'));
      drop.addEventListener('drop',e=>{
        e.preventDefault();
        drop.classList.remove('over');
        const proto = e.dataTransfer.getData('text/plain');
        const chip = selectedChip || [...document.querySelectorAll('.ch3Chip')].find(c=>c.dataset.proto === proto);
        if(chip) placeChip(drop, chip);
      });
    });

    bank.addEventListener('dragover',e=>e.preventDefault());
    bank.addEventListener('drop',e=>{
      e.preventDefault();
      if(selectedChip){
        bank.appendChild(selectedChip);
        selectedChip.classList.remove('selected','good','bad');
        selectedChip = null;
      }
    });

    const feedback = document.getElementById('ch3MatchFeedback');
    const scoreBox = document.getElementById('ch3MatchScore');
    const check = document.getElementById('ch3CheckMatch');
    const reset = document.getElementById('ch3ResetMatch');
    const original = ['HTTPS','DNS','SMTP','IMAP','SFTP','SSH','TCP','IP'];

    if(check) check.addEventListener('click',()=>{
      let score = 0, total = 0;
      document.querySelectorAll('.ch3TaskDrop').forEach(row=>{
        total++;
        const drop = row.querySelector('.ch3Drop');
        const chip = drop ? drop.querySelector('.ch3Chip') : null;
        const ok = chip && chip.dataset.proto === row.dataset.answer;
        if(drop) drop.classList.toggle('good',!!ok);
        if(drop) drop.classList.toggle('bad',!!chip && !ok);
        if(chip){
          chip.classList.toggle('good',!!ok);
          chip.classList.toggle('bad',!ok);
        }
        if(ok) score++;
      });
      if(scoreBox) scoreBox.textContent = `Score: ${score}/${total}`;
      if(feedback) feedback.textContent = score === total
        ? 'Excellent — every task has the correct application-layer protocol.'
        : `${score}/${total} correct. Move the red chip(s), then check again.`;
    });

    if(reset) reset.addEventListener('click',()=>{
      document.querySelectorAll('.ch3Drop .ch3Chip').forEach(c=>bank.appendChild(c));
      shuffleArray(original).forEach(proto=>{
        const chip = [...bank.querySelectorAll('.ch3Chip')].find(c=>c.dataset.proto === proto);
        if(chip) bank.appendChild(chip);
      });
      document.querySelectorAll('.ch3Chip').forEach(c=>c.classList.remove('selected','good','bad'));
      document.querySelectorAll('.ch3Drop').forEach(d=>d.classList.remove('good','bad','over'));
      selectedChip = null;
      if(scoreBox) scoreBox.textContent = 'Score: —';
      if(feedback) feedback.textContent = 'Drag a protocol chip into each matching task box. You can also click a chip, then click a drop box.';
    });
  }

  const orderBoard = document.getElementById('ch3OrderBoard');
  if(orderBoard){
    let dragged = null;
    const cards = () => [...orderBoard.querySelectorAll('.ch3OrderCard')];

    function clearOrderState(){
      cards().forEach(c=>c.classList.remove('good','bad'));
    }

    function getAfterElement(container, y){
      const els = [...container.querySelectorAll('.ch3OrderCard:not(.dragging)')];
      return els.reduce((closest, child)=>{
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;
        if(offset < 0 && offset > closest.offset){
          return {offset, element: child};
        }
        return closest;
      }, {offset: Number.NEGATIVE_INFINITY}).element;
    }

    cards().forEach(card=>{
      card.addEventListener('dragstart',e=>{
        dragged = card;
        card.classList.add('dragging');
        e.dataTransfer.effectAllowed = 'move';
      });
      card.addEventListener('dragend',()=>{
        card.classList.remove('dragging');
        dragged = null;
      });
      card.addEventListener('click',()=>{
        cards().forEach(c=>c.classList.remove('active'));
        card.classList.add('active');
      });
    });

    orderBoard.addEventListener('dragover',e=>{
      e.preventDefault();
      orderBoard.classList.add('over');
      const after = getAfterElement(orderBoard, e.clientY);
      if(!dragged) return;
      if(after == null) orderBoard.appendChild(dragged);
      else orderBoard.insertBefore(dragged, after);
    });
    orderBoard.addEventListener('dragleave',()=>orderBoard.classList.remove('over'));
    orderBoard.addEventListener('drop',()=>orderBoard.classList.remove('over'));

    const checkOrder = document.getElementById('ch3CheckOrder');
    const shuffleOrder = document.getElementById('ch3ShuffleOrder');
    const showOrder = document.getElementById('ch3ShowOrder');
    const orderFeedback = document.getElementById('ch3OrderFeedback');

    function setFeedback(text, ok=false){
      if(orderFeedback){
        orderFeedback.textContent = text;
        orderFeedback.style.color = ok ? '#176443' : '#8f3b1b';
      }
    }

    if(checkOrder) checkOrder.addEventListener('click',()=>{
      let score = 0;
      cards().forEach((card, idx)=>{
        const ok = Number(card.dataset.order) === idx + 1;
        card.classList.toggle('good', ok);
        card.classList.toggle('bad', !ok);
        if(ok) score++;
      });
      setFeedback(score === cards().length
        ? 'Correct sequence — the browser can now complete the web request.'
        : `${score}/${cards().length} cards are in the correct position. Rearrange the red cards.`, score === cards().length);
    });

    if(shuffleOrder) shuffleOrder.addEventListener('click',()=>{
      clearOrderState();
      const arr = cards();
      for(let i=arr.length-1;i>0;i--){
        const j = Math.floor(Math.random()*(i+1));
        [arr[i],arr[j]] = [arr[j],arr[i]];
      }
      arr.forEach(c=>orderBoard.appendChild(c));
      setFeedback('Shuffled. Drag the cards into the correct order.');
    });

    if(showOrder) showOrder.addEventListener('click',()=>{
      clearOrderState();
      cards().sort((a,b)=>Number(a.dataset.order)-Number(b.dataset.order)).forEach(c=>orderBoard.appendChild(c));
      cards().forEach(c=>c.classList.add('good'));
      setFeedback('Answer shown: URL → DNS → connection → HTTP request → HTTP response → render page.', true);
    });
    if(shuffleOrder) shuffleOrder.click();
  }

  // Randomize multiple-choice answers on every load
  document.querySelectorAll('.ch3QuizOptions').forEach(options=>shuffleChildren(options));

  document.querySelectorAll('.ch3QuizCard').forEach(card=>{
    card.querySelectorAll('.ch3QuizBtn').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const ok = btn.dataset.choice === card.dataset.answer;
        card.querySelectorAll('.ch3QuizBtn').forEach(b=>b.classList.remove('good','bad'));
        btn.classList.add(ok?'good':'bad');
        if(!ok){
          const correct = card.querySelector(`.ch3QuizBtn[data-choice="${card.dataset.answer}"]`);
          if(correct) correct.classList.add('good');
        }
      });
    });
  });
})();




